import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import doctorImage from "../../../assets/images/users-vector-icon-png_260862.jpg";

const doctors = [
  {
    name: "Dr. Calvin Carlo",
    specialty: "Eye Care",
    experience: "3 Years Experienced",
    image:
      "https://doctris-admin.vercel.app/static/media/01.d8b9651b2a3ba6336221.jpg",
  },
  {
    name: "Dr. Cristino Murphy",
    specialty: "Gynecology",
    experience: "5 Years Experienced",
    image:
      "https://doctris-admin.vercel.app/static/media/02.38e00cf46dc0cbd9fed3.jpg",
  },
  {
    name: "Dr. Alia Reddy",
    specialty: "Psychotherapy",
    experience: "4 Years Experienced",
    image:
      "https://doctris-admin.vercel.app/static/media/03.b192aca452235f61b392.jpg",
  },
  {
    name: "Dr. Toni Kovar",
    specialty: "Orthopedic",
    experience: "6 Years Experienced",
    image:
      "https://doctris-admin.vercel.app/static/media/04.f645789423636f851180.jpg",
  },
];

const DoctorCard = ({ name, specialty, experience, image }) => {
  return (
    <div className="flex items-center space-x-4 p-4 bg-gray-50 rounded-lg shadow-md mb-4">
      <img
        src={image}
        alt={name}
        className="w-20 h-20 rounded-full object-cover"
      />
      <div>
        <h3 className="text-lg font-semibold text-gray-900">{name}</h3>
        <p className="text-sm text-gray-600">{specialty}</p>
        <p className="text-sm text-gray-500">{experience}</p>
      </div>
    </div>
  );
};

const DoctorsList = () => {
  const [showAll, setShowAll] = useState(false);
  const navigate = useNavigate();

  // Show only the first 3 doctors if showAll is false
  const visibleDoctors = showAll ? doctors : doctors.slice(0, 4);

  return (
    <div className=" bg-white shadow-md p-5 rounded-lg w-[30%] h-auto">
      <h2 className="text-xl font-bold mb-6 text-gray-800">Doctors List</h2>
      <div className="space-y-5">
        {visibleDoctors.map((doctor, index) => (
          <DoctorCard
            key={index}
            name={doctor.name}
            specialty={doctor.specialty}
            experience={doctor.experience}
            image={doctor.image}
          />
        ))}
      </div>
      {/* Show View All Doctors button if there are more than 3 doctors */}
      {!showAll && doctors.length >= 1 && (
        <button
          onClick={() => navigate("/doctor")}
          className="mt-4 text-blue-600 hover:underline"
        >
          View All Doctors
        </button>
      )}
    </div>
  );
};

export default DoctorsList;
